<script>
  import { delay } from '@splendidlabz/utils'
  import { onMount } from 'svelte'
  import { init } from '../../../utils'
  import Icon from '../../Icon/Icon.svelte'

  let {
    show = $bindable(null),
    ref = $bindable(null),
    class: klass = '',
    componentName = 'PopoverTrigger',
    icon = 'tabler:menu',
    iconClass,
    target,
    children,
    onclick = null,
    ontoggle = null,
    onopen = null,
    onclose = null,
    ...rest
  } = $props()

  let popover = $state(null)

  init(() => {
    if (!target)
      throw new Error(`${componentName} must contain a target property`)
  })

  onMount(async _ => {
    await delay(0) // Gives time for popover to mount
    if (show) handleClick()
  })

  // ========================================
  // Event Listeners
  // ========================================
  function handleClick(event) {
    if (!popover) popover = document.querySelector(`#${target}`)
    popover.togglePopover()
    if (onclick) onclick(event)
  }

  // Allows trigger to know whether the popover is open or closed
  function handleToggle(event) {
    const { newState } = event.detail
    if (newState === 'open') {
      show = true
      if (onopen) onopen(event)
    }

    if (newState === 'closed') {
      show = false
      if (onclose) onclose(event)
    }

    if (ontoggle) ontoggle(event)
  }
</script>

<button
  {...rest}
  bind:this={ref}
  class="button popover-trigger {klass}"
  data-show={show}
  ontoggle={handleToggle}
  popovertarget={target}
>
  {#if children}
    {@render children()}
  {:else if icon}
    <Icon class={iconClass} {icon} />
  {/if}
</button>
